export const EXTENSION_TYPES=[{ctblTypeId:"queuedDelay",hostLockType:"password",sentinel:"CTBL_QUEUED_DELAY"}];export function isExtensionLock(e,n){if(!e||!e.lock)return!1;for(var o=null,t=0;t<EXTENSION_TYPES.length;t++)if(EXTENSION_TYPES[t].ctblTypeId===n){o=EXTENSION_TYPES[t];break}return!!o&&0===e.lock.indexOf(o.hostLockType)&&e.password===o.sentinel}export function getExtensionTypeForBlock(e){if(!e||!e.lock)return null;for(var n=0;n<EXTENSION_TYPES.length;n++){var o=EXTENSION_TYPES[n];if(0===e.lock.indexOf(o.hostLockType)&&e.password===o.sentinel)return o}return null}